// Expected strings were generated by running the originals (cloud-portal
// app/features/edge/proxy/metrics/queries.ts at a7010d0e, compute
// ui/consumer/src/lib/metrics-queries.ts at 285fb19d) with the same inputs, so
// a drift from either upstream shows up here.
import {
  albErrorRateQuery,
  albLatencyPercentilesQuery,
  albLatencyQuantileQuery,
  albRegionalRpsQuery,
  albRequestCountQuery,
  albRpsByClassQuery,
  albRpsQuery,
  albWafByOutcomeQuery,
  albWafIncreaseQuery,
  buildPrometheusLabelSelector,
  cpuUsageQuery,
  memoryUsageQuery,
  namesMatcher,
  resetGuardedIncrease,
  toStatusClassPatterns,
  workloadCpuSumQuery,
  workloadMemorySumQuery,
} from '..';

const scope = { projectId: 'proj-a', proxyId: 'gw-1' };
const TRAFFIC =
  '{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",gateway_namespace="default",label_topology_kubernetes_io_region!=""}';
const WAF = '{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",label_topology_kubernetes_io_region!=""}';

describe('ALB PromQL (portal parity)', () => {
  test('requests per second', () => {
    expect(albRpsQuery(scope, '1m')).toBe(`sum(rate(envoy_vhost_vcluster_upstream_rq${TRAFFIC}[1m]))`);
  });

  test('total requests, falling back to the raw counter', () => {
    expect(albRequestCountQuery(scope, '1h')).toBe(
      `sum(increase(envoy_vhost_vcluster_upstream_rq${TRAFFIC}[1h])) or sum(envoy_vhost_vcluster_upstream_rq${TRAFFIC})`
    );
  });

  test('requests per second by status class', () => {
    expect(albRpsByClassQuery(scope, '1h')).toBe(
      `sum by (envoy_response_code_class) (label_replace(rate(envoy_vhost_vcluster_upstream_rq${TRAFFIC}[1h]),"envoy_response_code_class","\${1}XX","envoy_response_code","([0-9]).*"))`
    );
  });

  test('error rate against unfiltered traffic', () => {
    expect(albErrorRateQuery(scope, '1m')).toBe(
      'sum(rate(envoy_vhost_vcluster_upstream_rq{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",gateway_namespace="default",label_topology_kubernetes_io_region!="",envoy_response_code=~"[45].."}[1m]))' +
        ` / sum(rate(envoy_vhost_vcluster_upstream_rq${TRAFFIC}[1m]))`
    );
    const [, denominator] = albErrorRateQuery({ ...scope, statusClasses: ['5XX'] }, '1m').split(' / ');
    expect(denominator).not.toContain('envoy_response_code');
  });

  test('p95 latency', () => {
    expect(albLatencyQuantileQuery(0.95, scope, '1m')).toBe(
      `histogram_quantile(0.95, sum(rate(envoy_vhost_vcluster_upstream_rq_time_bucket${TRAFFIC}[1m])) by (le))`
    );
  });

  test('p50 / p95 / p99 as labelled series', () => {
    const q = (n: number) =>
      `histogram_quantile(${n}, sum(rate(envoy_vhost_vcluster_upstream_rq_time_bucket${TRAFFIC}[1h])) by (le))`;
    expect(albLatencyPercentilesQuery(scope, '1h')).toBe(
      `label_replace(${q(0.5)},"quantile","p50","","") or ` +
        `label_replace(${q(0.95)},"quantile","p95","","") or ` +
        `label_replace(${q(0.99)},"quantile","p99","","")`
    );
  });

  test('requests per second by region', () => {
    expect(albRegionalRpsQuery(scope, '1h')).toBe(
      `sum(rate(envoy_vhost_vcluster_upstream_rq${TRAFFIC}[1h])) by (label_topology_kubernetes_io_region)`
    );
  });

  test('WAF events by outcome (no gateway_namespace on WAF series)', () => {
    const guarded = `(increase(coraza_envoy_filter_request_events_total${WAF}[1m]) * (resets(coraza_envoy_filter_request_events_total${WAF}[1m]) == bool 0))`;
    expect(albWafByOutcomeQuery(scope, '1h')).toBe(`sum by (coraza_outcome) (sum_over_time(${guarded}[1h:1m]))`);
  });

  test('WAF blocked + dropped', () => {
    const sel =
      '{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",label_topology_kubernetes_io_region!="",coraza_outcome=~"blocked|dropped"}';
    expect(albWafIncreaseQuery({ ...scope, customLabels: { coraza_outcome: '=~"blocked|dropped"' } }, '1h')).toBe(
      `sum((increase(coraza_envoy_filter_request_events_total${sel}[1h]) * (resets(coraza_envoy_filter_request_events_total${sel}[1h]) == bool 0)))`
    );
  });

  test('filters: regions, status classes', () => {
    expect(albRpsQuery({ ...scope, regions: ['us-east-1', 'us-central-1'], statusClasses: ['2XX'] }, '5m')).toBe(
      'sum(rate(envoy_vhost_vcluster_upstream_rq{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",gateway_namespace="default",label_topology_kubernetes_io_region!="",label_topology_kubernetes_io_region=~"us-east-1|us-central-1",envoy_response_code=~"2.."}[5m]))'
    );
    expect(toStatusClassPatterns(['', '1XX', '2XX'])).toEqual(['2..']);
    expect(toStatusClassPatterns(null)).toEqual([]);
  });

  test('resetGuardedIncrease and the selector builder', () => {
    expect(resetGuardedIncrease('some_counter_total', '{label="value"}', '30m')).toBe(
      '(increase(some_counter_total{label="value"}[30m]) * (resets(some_counter_total{label="value"}[30m]) == bool 0))'
    );
    expect(
      buildPrometheusLabelSelector({
        baseLabels: { project: 'p' },
        customLabels: { region: '!=""', env: 'prod' },
        filters: [
          { label: 'zone', value: ['a', 'b'] },
          { label: 'one', value: 'x' },
          { label: 'none', value: [] },
          { label: 'blank', value: '  ' },
        ],
      })
    ).toBe('{project="p",region!="",env="prod",zone=~"a|b",one="x"}');
  });
});

describe('compute PromQL (compute UI parity)', () => {
  test('instance CPU and memory', () => {
    expect(cpuUsageQuery('proj-a', 'web-0')).toBe(
      'sum(rate(datum_compute_instance_cpu_usage_seconds_total{resourcemanager_datumapis_com_project_name="proj-a",resource_name="web-0"}[2m]))'
    );
    expect(memoryUsageQuery('proj-a', 'web-0')).toBe(
      'sum(datum_compute_instance_memory_working_set_bytes{resourcemanager_datumapis_com_project_name="proj-a",resource_name="web-0"})'
    );
  });

  test('workload sums over its instances, escaping regex metacharacters', () => {
    const names = ['web-0', 'web-1', 'web.2'];
    expect(workloadCpuSumQuery('proj-a', names)).toBe(
      'sum(rate(datum_compute_instance_cpu_usage_seconds_total{resourcemanager_datumapis_com_project_name="proj-a",resource_name=~"web-0|web-1|web\\.2"}[2m]))'
    );
    expect(workloadMemorySumQuery('proj-a', names)).toBe(
      'sum(datum_compute_instance_memory_working_set_bytes{resourcemanager_datumapis_com_project_name="proj-a",resource_name=~"web-0|web-1|web\\.2"})'
    );
  });

  test('one instance is an exact match; none is no query', () => {
    expect(workloadCpuSumQuery('proj-a', ['web-0'])).toBe(cpuUsageQuery('proj-a', 'web-0'));
    expect(workloadCpuSumQuery('proj-a', [])).toBeUndefined();
    expect(namesMatcher('resource_name', ['a', 'a', ''])).toBe('resource_name="a"');
    expect(namesMatcher('resource_name', ['say "hi"'])).toBe('resource_name="say \\"hi\\""');
  });
});
